import { useEffect, useRef, useState } from 'react';
import { useKainBain } from '../../context/KainBainContext';
import { SkillsSection } from './SkillsSection';
import { SelectDropdown } from '../common/SelectDropdown';
import { ProjectSettingsForm } from './ProjectSettingsForm';
import { WorkflowManagementPanel } from './WorkflowManagementPanel';
import { SettingsSearchInput } from './SettingsSearchInput';

/***
 * MARK: PROJECT_SETTINGS_TABS
 * @description Single source of truth for the Project Settings tab bar: every
 *   tab's section id, button label + icon, tab-title heading, and whether the
 *   tab shares the one mounted `ProjectSettingsForm` (edits survive switches
 *   between form tabs; workflows/skills render their own panels). Adding a
 *   tab means adding one entry here — the buttons, the `h2` titles, and the
 *   section allowlists below all derive from this list so they cannot drift.
 *   App-wide UI & Workspace customization is NOT one of them — it lives in
 *   System Settings (SystemSettingsPage, `/system-settings`); per-project
 *   visual branding stays here as the accent-color picker inside the form.
 * @example PROJECT_SETTINGS_TABS.map((tab) => tab.id) => ['project', 'aliases', 'files', 'workflows', 'skills']
 ***/
export const PROJECT_SETTINGS_TABS = [
  {
    id: 'project',
    label: 'Project Settings',
    buttonIcon: '📂',
    heading: 'Project Configuration',
    headingIcon: '⚙️',
    sharesProjectForm: true,
  },
  {
    id: 'aliases',
    label: 'Aliases',
    buttonIcon: '🏷️',
    heading: 'Model Aliases',
    headingIcon: '🏷️',
    sharesProjectForm: true,
  },
  {
    id: 'files',
    label: 'Files & Links',
    buttonIcon: '📁',
    heading: 'Files & Links',
    headingIcon: '📁',
    sharesProjectForm: true,
  },
  {
    id: 'workflows',
    label: 'Named Workflows',
    buttonIcon: '🔀',
    heading: null,
    headingIcon: null,
    sharesProjectForm: false,
  },
  {
    id: 'skills',
    label: 'Skills',
    buttonIcon: '🧩',
    heading: null,
    headingIcon: null,
    sharesProjectForm: false,
  },
];

/***
 * MARK: PROJECT_SETTINGS_SECTIONS
 * @description Allowlisted sub-sections of the Project Settings page, derived
 *   from `PROJECT_SETTINGS_TABS` so the allowlist and the tab bar agree.
 * @example PROJECT_SETTINGS_SECTIONS.includes('aliases') => true
 ***/
export const PROJECT_SETTINGS_SECTIONS = PROJECT_SETTINGS_TABS.map((tab) => tab.id);

/***
 * MARK: PROJECT_FORM_SECTIONS
 * @description The project-related tabs share one mounted `ProjectSettingsForm`
 *   (edits survive tab switches); workflows/skills render their own panels.
 *   Derived from `PROJECT_SETTINGS_TABS` so a new form tab needs no second edit.
 * @example PROJECT_FORM_SECTIONS.includes('files') => true
 ***/
export const PROJECT_FORM_SECTIONS = PROJECT_SETTINGS_TABS.filter(
  (tab) => tab.sharesProjectForm,
).map((tab) => tab.id);

// How the jump-to-setting highlight behaves: a short wait lets the newly
// selected tab render before scrolling, then the ring stays visible briefly
// so the eye lands on the right field before it clears.
const HIGHLIGHT_SHOW_DELAY_MS = 80;
const HIGHLIGHT_HIDE_DELAY_MS = 2100;

/***
 * MARK: ProjectSettings
 * @description A dedicated Project Management / Settings page for configuring
 * the active project across focused tabs — Project (basics + retry/timeouts),
 * Aliases (model aliases), Files & Links (paths, repos, app link) — plus
 * multiple named workflows, and skills.
 * App-wide UI & Workspace customization lives in System Settings
 * (SystemSettingsPage, `/system-settings`). Distinct from that platform-scoped
 * screen, this page is per-project and keeps the `/settings` route.
 * @example <ProjectSettings />
 ***/
export function ProjectSettings() {
  const { projects, activeProjectId, selectProject } = useKainBain();
  const activeProject = projects.find((p) => p.id === activeProjectId);
  const [settingsSection, setSettingsSection] = useState('project');
  // Fail-safe: an unknown section id (e.g. a stale 'ui' from before UI
  // customization moved to System Settings) falls back to the project form
  // instead of rendering a blank page.
  const effectiveSection = PROJECT_SETTINGS_SECTIONS.includes(settingsSection)
    ? settingsSection
    : 'project';
  // Jump-to-setting target: `{ id, at }` so repeating the same search still
  // re-fires the highlight effect below (object identity changes each time).
  // `at` is a monotonic counter (not Date.now()): the value only needs to be
  // unique per selection, and a counter keeps the update pure and testable.
  const [highlightTarget, setHighlightTarget] = useState(null);
  const highlightSeqRef = useRef(0);
  // Fail-safe: `effectiveSection` is always a known tab, but the lookup still
  // falls back to the first tab so a heading always renders (never blank).
  const activeTab =
    PROJECT_SETTINGS_TABS.find((tab) => tab.id === effectiveSection) ?? PROJECT_SETTINGS_TABS[0];
  // Unsaved-edits flag reported by the shared project form.
  const [formDirty, setFormDirty] = useState(false);
  // Focus targets for arrow-key tab navigation (automatic activation: moving
  // focus also selects the tab, matching the APG tabs pattern).
  const tabButtonRefs = useRef([]);
  /***
   * MARK: handleSectionChange
   * @description Tab switch guard: leaving the project-related tabs
   *   (Project/Aliases/Files & Links) with unsaved edits asks for
   *   confirmation first. Moving between project tabs never warns — the
   *   shared form stays mounted and keeps the edits.
   ***/
  const handleSectionChange = (nextSection) => {
    if (
      formDirty &&
      PROJECT_FORM_SECTIONS.includes(effectiveSection) &&
      !PROJECT_FORM_SECTIONS.includes(nextSection) &&
      typeof window !== 'undefined' &&
      typeof window.confirm === 'function' &&
      !window.confirm('You have unsaved changes. Switch tabs anyway?')
    ) {
      return;
    }
    setSettingsSection(nextSection);
  };
  const focusTabAt = (index) => {
    const count = PROJECT_SETTINGS_TABS.length;
    const wrapped = ((index % count) + count) % count;
    tabButtonRefs.current[wrapped]?.focus();
    handleSectionChange(PROJECT_SETTINGS_TABS[wrapped].id);
  };
  // Arrow-key navigation between tabs (APG automatic activation: moving
  // focus also selects the tab). Wired per-button rather than on the tablist
  // container so the handler always lives on a focusable element. Movement is
  // relative to the focused tab: if the dirty-guard blocks a switch, focus
  // and selection can briefly diverge, and focus-relative movement stays sane.
  const onTabKeyDown = (event, fromIndex) => {
    if (event.key === 'ArrowRight') {
      event.preventDefault();
      focusTabAt(fromIndex + 1);
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault();
      focusTabAt(fromIndex - 1);
    } else if (event.key === 'Home') {
      event.preventDefault();
      focusTabAt(0);
    } else if (event.key === 'End') {
      event.preventDefault();
      focusTabAt(PROJECT_SETTINGS_TABS.length - 1);
    }
  };

  /***
   * MARK: handleSearchSelect
   * @description Jumps to a search result: switches to the entry's tab, then
   *   the highlight effect scrolls the target into view and rings it.
   ***/
  const handleSearchSelect = (entry) => {
    if (!entry) return;
    handleSectionChange(entry.tab);
    highlightSeqRef.current += 1;
    setHighlightTarget({ id: entry.elementId, at: highlightSeqRef.current });
  };

  // Scrolls the search target into view and highlights it briefly. Guarded
  // for test DOMs without `scrollIntoView`, and no-ops when the target id
  // is not on the active tab (e.g. a conditional field). Cleanup removes the
  // ring from the previous target: without this, picking a second result
  // while the first ring is still showing would clear the first hide timer
  // and leave that ring stuck on forever.
  useEffect(() => {
    if (!highlightTarget) return undefined;
    const targetId = highlightTarget.id;
    const clearRing = () => {
      const el = typeof document !== 'undefined' ? document.getElementById(targetId) : null;
      el?.classList?.remove('ring-2', 'ring-primary', 'rounded-sm');
    };
    const showTimer = setTimeout(() => {
      const el = typeof document !== 'undefined' ? document.getElementById(targetId) : null;
      if (el) {

[113 more lines in file. Use offset=201 to continue.]

        if (typeof el.scrollIntoView === 'function') {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
        el.classList.add('ring-2', 'ring-primary', 'rounded-sm');
      }
    }, HIGHLIGHT_SHOW_DELAY_MS);
    const hideTimer = setTimeout(clearRing, HIGHLIGHT_HIDE_DELAY_MS);
    return () => {
      clearTimeout(showTimer);
      clearTimeout(hideTimer);
      clearRing();
    };
  }, [highlightTarget, effectiveSection]);

  return (
    /* A named <section> landmark (NOT another <main>): the app shell already
       provides the single top-level <main id="main-content"> (App.jsx), and a
       nested main triggers axe landmark violations. A labelled section keeps
       the settings content inside a landmark without duplicating main. */
    <section
      aria-label="Project settings"
      className="flex-1 p-6 space-y-6 overflow-y-auto custom-scrollbar text-on-surface bg-surface-deep"
    >
      {/* Top section switcher (tabs left, settings search right) */}
      <div className="flex gap-2 justify-between items-center border-b border-border-standard pb-4">
        <div className="flex gap-2 flex-wrap" role="tablist" aria-label="Project settings sections">
          {PROJECT_SETTINGS_TABS.map((tab, index) => (
            <button
              key={tab.id}
              ref={(el) => {
                tabButtonRefs.current[index] = el;
              }}
              id={`project-settings-tab-${tab.id}`}
              type="button"
              role="tab"
              aria-selected={effectiveSection === tab.id}
              aria-controls="project-settings-tabpanel"
              onClick={() => handleSectionChange(tab.id)}
              onKeyDown={(event) => onTabKeyDown(event, index)}
              className={`px-4 py-2 text-xs font-bold uppercase tracking-wider rounded-sm transition-all flex items-center gap-2 cursor-pointer ${
                effectiveSection === tab.id
                  ? 'bg-primary text-on-primary font-bold shadow-sm'
                  : 'bg-surface-container hover:bg-surface-container-high text-text-muted hover:text-on-surface'
              }`}
            >
              <span aria-hidden="true">{tab.buttonIcon}</span>
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
        <div className="shrink-0">
          <SettingsSearchInput onSelect={handleSearchSelect} />
        </div>
      </div>

      <div
        id="project-settings-tabpanel"
        role="tabpanel"
        aria-labelledby={`project-settings-tab-${effectiveSection}`}
      >
        {PROJECT_FORM_SECTIONS.includes(effectiveSection) && (
          <div>
            {/* Every project-related tab gets an h2 tab title: the section
              components below use h3 subtitles, and starting at h3 would skip
              a heading level (axe heading-order violation). */}
            <h2 className="text-lg font-bold uppercase tracking-tight text-text-high mb-4 flex items-center gap-2 font-headline-md">
              <span className="text-primary">{activeTab.headingIcon}</span> {activeTab.heading}
            </h2>
            {effectiveSection === 'project' && (
              <div className="space-y-4 max-w-2xl mb-8">
                <div className="flex flex-col gap-2">
                  <label
                    htmlFor="active-project-select"
                    className="text-xs font-bold uppercase text-text-muted tracking-wider"
                  >
                    Active Project
                  </label>
                  <SelectDropdown
                    id="active-project-select"
                    ariaLabel="Active Project"
                    value={activeProjectId || ''}
                    onChange={selectProject}
                    options={projects.map((p) => ({ value: p.id, label: p.name }))}
                  />
                </div>
              </div>
            )}

            {/* One mounted form across the project-related tabs: edits survive
              tab switches because only the `section` prop changes. */}
            <ProjectSettingsForm
              key={activeProjectId}
              project={activeProject}
              projectId={activeProjectId}
              onProjectUpdated={selectProject}
              section={effectiveSection}
              onDirtyChange={setFormDirty}
            />
          </div>
        )}

        {effectiveSection === 'workflows' && (
          <WorkflowManagementPanel key={activeProjectId} projectId={activeProjectId} />
        )}

        {effectiveSection === 'skills' && (
          <SkillsSection key={activeProjectId} activeProjectId={activeProjectId} />
        )}
      </div>
    </section>
  );
}

import { useState, useRef, useCallback, useEffect } from 'react';
import { useKainBain } from '../../context/KainBainContext';
import { api } from '../../services/api';
import { logger } from '../../services/logger';
import { useModelCatalog } from '../../hooks/useModelCatalog';
import { FALLBACK_MODELS } from '../stageTypes';
import { resolveStoredModelValidity } from '../common/ModelSelector';
import { ModelAliasesSection, validateAliasList } from './ModelAliasesSection';
import { accentTokens } from '../../theme/accentTokens';
import { ALIAS_HARNESS_ID, findAliasUsages } from '../../../../shared/modelAliases.js';
import { msToMinutes } from '../../utils/timeoutUnits';
import { parseRetrySettings } from './projectSettingsValidation';
import { ProjectBasicsSection } from './ProjectBasicsSection';
import { RetryTimeoutsSection } from './RetryTimeoutsSection';
import { PathsAndReposSection } from './PathsAndReposSection';

/***
 * MARK: ProjectSettingsForm
 * @description Keyed form that initializes its state from the active project.
 * Manages project name, agent harness + default model (one wired control: the
 * harness scopes the model catalogue — list dropdown, empty state, or
 * hidden — per the harness's `modelSelection`), the custom harness's
 * free-text command line (model flags bake into the command itself),
 * accent color theme, working directory, notes directory,
 * Git remote URL, and the per-project retry/timeout overrides.
 * The form stays mounted across the project-related tabs (project, aliases,
 * files) so edits survive tab switches — the `section` prop only selects
 * which blocks render. Dirty state is reported through `onDirtyChange` so
 * the tab bar can warn before leaving with unsaved edits.
 * @param {Object} props
 * @param {Object} props.project - The current project object.
 * @param {string} props.projectId - Active project identifier.
 * @param {Function} props.onProjectUpdated - Callback when project is updated.
 * @param {string} [props.section] - Visible tab ('project'|'aliases'|'files').
 * @param {Function} [props.onDirtyChange] - Called with true/false as edits are made or saved.
 * @example <ProjectSettingsForm project={project} projectId="p1" onProjectUpdated={select} section="aliases" onDirtyChange={setDirty} />
 ***/
export function ProjectSettingsForm({
  project,
  projectId,
  onProjectUpdated,
  section = 'project',
  onDirtyChange,
}) {
  // Fail-safe: an unknown section id renders the project tab instead of a
  // blank page. This list mirrors PROJECT_FORM_SECTIONS in ProjectSettings.jsx
  // (kept local to avoid a render-cycle import between the tab bar and the
  // form); the "tab config, section allowlists, and search index agree"
  // test pins them together, so adding a form tab means updating both.
  const activeFormSection = ['project', 'aliases', 'files'].includes(section)
    ? section
    : 'project';
  const {
    notifySuccess,
    notifyError,
    hiddenProjectIds = [],
    toggleHideProject,
    updateProjectInState,
    isHarnessDisabled,
  } = useKainBain();
  const [projectName, setProjectName] = useState(project?.name || '');
  const [defaultModel, setDefaultModel] = useState(project?.defaultModel || '');
  // Agent harness selection: '' means "follow the configured default" (the
  // backend resolves config.defaultHarness → "pi"). This single state drives
  // BOTH the harness dropdown and the model catalogue (ModelSelector is
  // controlled below), so the picked model always belongs to the picked
  // harness. Selecting "custom" additionally needs a free-text command line
  // (project.harnessCommand) — model flags bake into the command itself.
  const [harness, setHarness] = useState(project?.harness || '');
  const [harnessCommand, setHarnessCommand] = useState(project?.harnessCommand || '');
  // Per-project model aliases (table state lives here so the save payload
  // carries it; the section edits through setModelAliases).
  const [modelAliases, setModelAliases] = useState(
    Array.isArray(project?.modelAliases) ? project.modelAliases : [],
  );
  const [modelAliasesTouched, setModelAliasesTouched] = useState(false);
  const [accentColor, setAccentColor] = useState(project?.accentColor || '#7bdb85');
  const [cwd, setCwd] = useState(project?.cwd || '');
  // D13: no host default baked in — '' (unset) lets the server resolve the
  // configured notes root (or report notes-missing loudly) instead of
  // persisting one operator's path into every fresh project.
  const [notesDir, setNotesDir] = useState(project?.notesDir || project?.notesPath || '');
  const [docsDirName, setDocsDirName] = useState(project?.docsDirName || '');
  const [kainbainDirName, setKainbainDirName] = useState(project?.kainbainDirName || '');
  const [centralizedDocs, setCentralizedDocs] = useState(project?.centralizedDocs !== false);
  const [gitRepo, setGitRepo] = useState(project?.gitRepo || project?.gitUrl || '');
  // Per-task branch support (kb/<taskId> branches + merge-to-main stage).
  // Opt-in: defaults off so existing single-branch projects are unaffected.
  const [useBranches, setUseBranches] = useState(project?.useBranches === true);
  // Preserved PR-review diff across merge + deploy (opt-in, default off) and
  // the per-merge baseline reset (default on: each merge pass re-scopes the
  // review to that pass's change; off keeps a cumulative view instead).
  const [preserveReviewDiff, setPreserveReviewDiff] = useState(
    project?.preserveReviewDiffAfterMerge === true,
  );
  const [resetReviewBaseline, setResetReviewBaseline] = useState(
    project?.resetReviewBaselineOnMerge !== false,
  );
  // Retry & timeout overrides: raw string drafts ('' = unset = follow the
  // global default), so blanking a field reads clearly and partial input
  // stays editable while typing. Timeout drafts are entered in minutes but
  // stored in milliseconds, so they convert through the shared helper; the
  // auto-iteration switch is tri-state: 'default' (follow global),
  // 'enabled', or 'disabled'.
  const retryDraft = (stored) => (stored === undefined || stored === null ? '' : String(stored));
  const retryDraftMinutes = (storedMs) => {
    const minutes = msToMinutes(storedMs);
    return minutes === '' ? '' : String(minutes);
  };
  const retrySwitch = (stored) => {
    if (stored === true) return 'enabled';
    if (stored === false) return 'disabled';
    return 'default';
  };
  const [maxAutoIterations, setMaxAutoIterations] = useState(
    retryDraft(project?.maxAutoIterations),
  );
  const [maxTransientRetries, setMaxTransientRetries] = useState(
    retryDraft(project?.maxTransientRetries),
  );
  const [autoIterationEnabled, setAutoIterationEnabled] = useState(
    retrySwitch(project?.autoIterationEnabled),
  );
  const [agentTimeoutMs, setAgentTimeoutMs] = useState(retryDraftMinutes(project?.agentTimeoutMs));
  const [ciTimeoutMs, setCiTimeoutMs] = useState(retryDraftMinutes(project?.ciTimeoutMs));
  const [mergeTimeoutMs, setMergeTimeoutMs] = useState(retryDraftMinutes(project?.mergeTimeoutMs));
  const [retryErrors, setRetryErrors] = useState({});
  // Unsaved-edits tracking: any draft change flips the ref; a successful
  // save or a project switch clears it. The post-render effect below reports
  // the current value through `onDirtyChange` so the tab bar can warn before
  // leaving with unsaved edits. (A ref — not state — so marking dirty never
  // re-renders on its own; the setter call that follows already does.)
  // Declared BEFORE the branch-sync block below so the reset effect further
  // down can observe the project identity the fields were synced from.
  const dirtyRef = useRef(false);
  const markDirty = useCallback(() => {
    dirtyRef.current = true;
    // Report synchronously too: the debounced effect below re-reports on the
    // next render, but waiting for it can leave the parent tab guard stale by
    // one interaction when an edit is immediately followed by a tab click.
    onDirtyChange?.(true);
  }, [onDirtyChange]);
  // Wraps a draft setter so the edit also marks the form dirty.
  const touch = useCallback(
    (setter) => (value) => {
      markDirty();
      setter(value);
    },
    [markDirty],
  );
  // Sync form state once the project object loads WITHOUT an effect
  // (react-hooks/set-state-in-effect): adjust state during render when the
  // project identity changes — the documented React alternative to
  // sync-effects. Covers the form mounting before the project fetch resolves.
  // EVERY persisted field must be listed here: anything left on its
  // mount-time placeholder is sent back on Save and clobbers the stored
  // value (seen in prod: name '' + cwd set to the projects root, which
  // orphaned project.json and broke all branch operations).
  const [branchSyncProjectId, setBranchSyncProjectId] = useState(project?.id);
  if ((project?.id ?? null) !== (branchSyncProjectId ?? null)) {
    setBranchSyncProjectId(project?.id ?? null);
    setProjectName(project?.name || '');
    setCwd(project?.cwd || '');
    setNotesDir(project?.notesDir || project?.notesPath || '');
    setDocsDirName(project?.docsDirName || '');
    setKainbainDirName(project?.kainbainDirName || '');
    setCentralizedDocs(project?.centralizedDocs !== false);
    setGitRepo(project?.gitRepo || project?.gitUrl || '');
    setAccentColor(project?.accentColor || '#7bdb85');
    setUseBranches(project?.useBranches === true);
    setPreserveReviewDiff(project?.preserveReviewDiffAfterMerge === true);
    setResetReviewBaseline(project?.resetReviewBaselineOnMerge !== false);
    setHarness(project?.harness || '');
    setHarnessCommand(project?.harnessCommand || '');
    setMaxAutoIterations(retryDraft(project?.maxAutoIterations));
    setMaxTransientRetries(retryDraft(project?.maxTransientRetries));
    setAutoIterationEnabled(retrySwitch(project?.autoIterationEnabled));
    setAgentTimeoutMs(retryDraftMinutes(project?.agentTimeoutMs));
    setCiTimeoutMs(retryDraftMinutes(project?.ciTimeoutMs));
    setMergeTimeoutMs(retryDraftMinutes(project?.mergeTimeoutMs));
    setRetryErrors({});
    if (!modelAliasesTouched) {
      setModelAliases(Array.isArray(project?.modelAliases) ? project.modelAliases : []);
    }
  }
  // Shared model catalogue (flat models + per-harness view) with the app-wide
  // fallback semantics; ProjectSettings keeps its own curated fallback list.
  // The per-harness view carries each harness's `modelSelection` mode, so the
  // single harness control below always renders the matching model UI.
  // `refresh` re-runs discovery past both caches (empty-state escape hatch).
  const { models, harnesses, refreshing, refresh } = useModelCatalog(FALLBACK_MODELS, {
    // Live draft state (not the persisted project prop): rows added or edited
    // in the Model Aliases section below appear in this page's own picker
    // before saving. Invalid rows are dropped by normalization, so the picker
    // previews exactly what saving will offer.
    aliases: modelAliases,
  });
  const [saveState, setSaveState] = useState('idle');
  const [validationError, setValidationError] = useState('');
  // Soft combination warnings returned by the last save (the save succeeded;

